def with_fallback(fn, fallback):
    try:
        return fn()
    except (TimeoutError, ConnectionError):
        return fallback

def slow():
    raise TimeoutError("no answer within 0.1 s")

out = [with_fallback(slow, "(title unavailable)")]
try:
    out.append(with_fallback(lambda: 1 / 0, "(title unavailable)"))
except ZeroDivisionError:
    out.append("bug raised")
print(out)

def body_problems(expected, actual, rules, path="$"):
    problems = []
    for key, value in expected.items():
        p = f"{path}.{key}"
        if key not in actual:
            problems.append(f"{p}: missing")
        elif rules.get(p) == "type" and type(actual[key]) is not type(value):
            problems.append(f"{p}: expected {type(value).__name__}, got {type(actual[key]).__name__}")
        elif rules.get(p) != "type" and actual[key] != value:
            problems.append(f"{p}: expected {value!r}")
    return problems

rules = {"$.title": "type", "$.available": "type"}
print(body_problems({"title": "Dune", "available": True, "id": "b1"},
                    {"name": "Dune", "available": "yes", "id": "b1", "isbn": "x"}, rules))
